#!/usr/bin/env node
/**
 * Builds the Code app index (spec 06): only allowlisted files of THIS portfolio, validated
 * before publication. Any path escape, unexpected file or secret-looking content fails the run.
 * Output is git-ignored and regenerated by predev/prebuild/pretypecheck/pretest.
 */
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { existsSync, lstatSync, mkdirSync, readFileSync, realpathSync, writeFileSync } from "node:fs";
import { dirname, extname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const OUTPUT = "src/features/workstation/code/generated/code-index.json";
const ALLOWED_ROOTS = ["src/components/", "src/features/", "src/graphics/", "src/theme/", "src/styles/", "scripts/generate-workstation-code.mjs"];
const EXTENSIONS = new Map([[".ts", "ts"], [".tsx", "tsx"], [".css", "css"], [".mjs", "js"]]);
const MAX_BYTES = 120_000;

/**
 * Explicit manifest: component id → fixed path. Groups are translated in the client.
 * @type {Array<[group: string, id: string, path: string]>}
 */
export const MANIFEST = [
  ["notebook", "workstation-scene", "src/features/workstation/scene/WorkstationScene.client.tsx"],
  ["notebook", "laptop-model", "src/features/workstation/models/LaptopModel.client.tsx"],
  ["notebook", "motion-rig", "src/features/workstation/orchestrator/position.ts"],
  ["notebook", "trajectory", "src/features/workstation/orchestrator/trajectory.ts"],
  ["notebook", "rigid-body", "src/features/workstation/physics/body.ts"],
  ["notebook", "impact-reaction", "src/features/workstation/physics/impact-reaction.ts"],
  ["notebook", "workbench-screen", "src/features/workstation/screen/WorkbenchScreen.client.tsx"],
  ["notebook", "scroll-inertia", "src/features/workstation/physics/scroll-inertia.ts"],
  ["notebook", "hinge", "src/features/workstation/physics/hinge.ts"],
  ["notebook", "notebook-sound", "src/features/workstation/audio/notebook-sound.ts"],
  ["notebook", "page-reactions", "src/features/workstation/page/page-reactions.ts"],
  ["notebook", "orchestrator", "src/features/workstation/orchestrator/WorkstationOrchestrator.client.tsx"],
  ["notebook", "state-machine", "src/features/workstation/state/workstation-machine.ts"],
  ["notebook", "terminal-commands", "src/features/workstation/terminal/commands.ts"],
  ["notebook", "code-highlight", "src/features/workstation/code/highlight.ts"],
  ["notebook", "code-generator", "scripts/generate-workstation-code.mjs"],
  ["page", "hero-editorial", "src/components/hero/HeroEditorial.tsx"],
  ["page", "site-header", "src/components/layout/SiteHeader.tsx"],
  ["page", "theme-toggle", "src/components/ui/ThemeToggle.client.tsx"],
  ["page", "project-carousel", "src/components/carousel/ProjectCarousel.client.tsx"],
  ["page", "carousel-countdown", "src/components/carousel/CarouselCountdown.client.tsx"],
  ["page", "project-card", "src/components/projects/ProjectCard.tsx"],
  ["page", "journey-timeline", "src/components/timeline/JourneyTimeline.client.tsx"],
  ["page", "section-shell", "src/components/sections/Section.tsx"],
  ["page", "expertise-section", "src/components/sections/ExpertiseSection.tsx"],
  ["page", "services-section", "src/components/sections/ServicesSection.tsx"],
  ["page", "contact-section", "src/components/sections/ContactSection.tsx"],
  ["page", "site-footer", "src/components/layout/SiteFooter.tsx"],
  ["motion", "motion-engine", "src/features/motion/motion-engine.ts"],
  ["motion", "hero-scene", "src/graphics/hero/HeroScene.client.tsx"],
  ["motion", "theme-client", "src/theme/theme-client.ts"],
  ["styles", "workstation-css", "src/styles/workstation.css"],
  ["styles", "tokens-css", "src/styles/tokens.css"],
];

/** Heuristics only; a clean scan is not proof of absence, so the manifest stays explicit. */
export const SECRET_PATTERNS = [
  /-----BEGIN [A-Z ]*PRIVATE KEY-----/,
  /\bAKIA[0-9A-Z]{16}\b/,
  /\bgh[pousr]_[A-Za-z0-9]{36,}\b/,
  /\bsk_(?:live|test)_[A-Za-z0-9]{16,}\b/,
  /\bxox[abprs]-[A-Za-z0-9-]{10,}\b/,
  /\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/,
  /\b(?:api[_-]?key|secret|passwd|password|auth[_-]?token|access[_-]?token)\s*[:=]\s*["'][^"'\s]{12,}["']/i,
];
const DENIED_SEGMENTS = /(^|\/)(\.env[^/]*|.*secret.*|.*credential.*|.*\.pem|.*\.key|node_modules|\.git)(\/|$)/i;

export function validatePath(path, root = ROOT) {
  if (typeof path !== "string" || !path || path.includes("\\") || path.includes("\0") || path.startsWith("/") || /^[a-z]:/i.test(path)) throw new Error(`Invalid path: ${path}`);
  if (path.split("/").some((segment) => segment === ".." || segment === ".")) throw new Error(`Relative segment in ${path}`);
  if (DENIED_SEGMENTS.test(path)) throw new Error(`Denied path: ${path}`);
  if (!ALLOWED_ROOTS.some((allowed) => allowed.endsWith("/") ? path.startsWith(allowed) : path === allowed)) throw new Error(`Outside allowed roots: ${path}`);
  const language = EXTENSIONS.get(extname(path));
  if (!language) throw new Error(`Unexpected extension: ${path}`);
  const absolute = resolve(root, path);
  if (!existsSync(absolute)) throw new Error(`Missing file: ${path}`);
  if (lstatSync(absolute).isSymbolicLink()) throw new Error(`Symlink refused: ${path}`);
  // A symlinked parent directory or any escape changes the canonical relative path.
  const real = realpathSync(absolute);
  if (relative(realpathSync(root), real).split(sep).join("/") !== path) throw new Error(`Path escapes repository: ${path}`);
  return { absolute: real, language };
}

export function scanSecrets(content, path) {
  for (const pattern of SECRET_PATTERNS) if (pattern.test(content)) throw new Error(`Secret-like content refused in ${path} (${pattern.source.slice(0, 24)}…)`);
}

function git(args, fallback = "", cwd = ROOT) {
  // Porcelain starts with two status columns, including a significant leading space.
  try { return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trimEnd(); } catch { return fallback; }
}
function repositoryUrl(root) {
  const remote = git(["config", "--get", "remote.origin.url"], "", root);
  const match = /github\.com[:/]([\w.-]+)\/([\w.-]+?)(?:\.git)?$/.exec(remote);
  return match ? `https://github.com/${match[1]}/${match[2]}` : null;
}

export function buildIndex({ root = ROOT, manifest = MANIFEST } = {}) {
  const sha = process.env.WORKSTATION_CODE_SHA || process.env.VERCEL_GIT_COMMIT_SHA || git(["rev-parse", "HEAD"], "unknown", root);
  const status = git(["status", "--porcelain=v1", "-z", "--untracked-files=all", "--", ...manifest.map(([, , path]) => path)], "", root).split("\0");
  const dirty = new Set();
  for (let i = 0; i < status.length; i++) {
    if (status[i].length < 4) continue;
    dirty.add(status[i].slice(3));
    if (/[RC]/.test(status[i].slice(0, 2))) i++; // -z puts the old rename/copy path in the next field.
  }
  const repository = repositoryUrl(root), ids = new Set();
  // Local handoff commits may not exist on GitHub yet. A clean file alone is not enough
  // to promise a working link; require a known origin ref or the build provider's commit.
  const published = sha !== "unknown" && (
    Boolean(git(["for-each-ref", "--format=%(refname)", "--contains", sha, "refs/remotes/origin"], "", root)) ||
    process.env.VERCEL_GIT_COMMIT_SHA === sha ||
    (process.env.GITHUB_ACTIONS === "true" && process.env.GITHUB_SHA === sha)
  );
  const files = manifest.map(([group, id, path]) => {
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(id) || ids.has(id)) throw new Error(`Invalid or duplicate id: ${id}`);
    ids.add(id);
    const { absolute, language } = validatePath(path, root);
    const content = readFileSync(absolute, "utf8");
    if (Buffer.byteLength(content) > MAX_BYTES) throw new Error(`File too large for the Code app: ${path}`);
    scanSecrets(content, path);
    const changed = dirty.has(path);
    return {
      id, group, path, language, lines: content.split("\n").length, bytes: Buffer.byteLength(content),
      sha256: createHash("sha256").update(content).digest("hex"), dirty: changed,
      url: repository && published && !changed ? `${repository}/blob/${sha}/${path}` : null,
      content,
    };
  });
  return { version: 1, sha, published, files };
}

function main() {
  const index = buildIndex(), target = join(ROOT, OUTPUT), json = `${JSON.stringify(index)}\n`;
  mkdirSync(dirname(target), { recursive: true });
  const previous = existsSync(target) ? readFileSync(target, "utf8") : "";
  if (previous !== json) writeFileSync(target, json);
  console.log(`workstation code index: ${index.files.length} files · ${index.sha.slice(0, 7)}${index.files.some((file) => file.dirty) ? " · dirty" : ""}`);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  try { main(); } catch (error) { console.error(`workstation code index failed: ${error instanceof Error ? error.message : error}`); process.exit(1); }
}
